                    match = re.search(r'^ +', self.line)
                    if match is not None:
                        indent = match.group()
                    else:
                        indent = ''
                    yield sql.Token(T.Whitespace, f'\n{indent}')
                    self.line = indent
                self.line += val
            yield token

